sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    try {
        var rest = new sn_ws.RESTMessageV2('Groq API', 'POST');

        var cat = current.getValue('complaint_category') || 'General';
        var desc = (current.getValue('short_description') || '') + ' ' + (current.getValue('description') || '');

        rest.setStringParameterNoEscape('category', cat);
        rest.setStringParameterNoEscape('description', desc);

        var response = rest.execute();
        var httpStatus = response.getStatusCode();

        if (httpStatus === 200) {
            var body = JSON.parse(response.getBody());
            var rawContent = body.choices[0].message.content;

            // Extract JSON object if model outputs explanatory text around it
            var jsonMatch = rawContent.match(/\{[\s\S]*\}/);
            var parsed = JSON.parse(jsonMatch ? jsonMatch[0] : rawContent);

            var gr = new GlideRecord('x_1958581_retail_0_retail_complaint');
            if (gr.get(current.getUniqueValue())) {
                gr.setValue('business_risk', parsed.business_risk);
                gr.setValue('sentiment', parsed.sentiment);
                gr.setValue('priority', parsed.priority);
                gr.update();
            }
        } else {
            gs.error('Groq AI API error: ' + httpStatus + ' - ' + response.getBody());
        }
    } catch (ex) {
        gs.error('Groq AI Execution failed: ' + ex.getMessage());
    }

})(current, previous);
